export const formatCurrency = (val: number): string => {
  return new Intl.NumberFormat('ja-JP', {
    style: 'currency',
    currency: 'JPY',
    maximumFractionDigits: 0,
  }).format(val);
};

export const formatNumber = (val: number): string => {
  return new Intl.NumberFormat('ja-JP').format(Math.round(val));
};

export const filterRecordsByPeriod = (
  records: MonthlyRecord[] = monthlyRecords,
  period: FilterPeriod = 'all'
): MonthlyRecord[] => {
  const safeRecords = Array.isArray(records) ? records : [];
  switch (period) {
    case 'first-half':
      return safeRecords.slice(0, 6);
    case 'second-half':
      return safeRecords.slice(6, 12);
    case 'all':
    default:
      return [...safeRecords];
  }
};

export const calculateKpiSummary = (records: MonthlyRecord[] = []): KpiCardData[] => {
  const safeRecords = Array.isArray(records) ? records : [];

  if (safeRecords.length === 0) {
    return [
      {
        title: '売上高',
        value: '0',
        subValue: '目標達成率 0.0%',
        changeRate: 0,
        isPositive: true,
        unit: '円',
        type: 'sales',
      },
      {
        title: '客数',
        value: '0',
        subValue: '月平均 0人',
        changeRate: 0,
        isPositive: true,
        unit: '人',
        type: 'customers',
      },
      {
        title: '平均単価',
        value: '0',
        subValue: '最高単価 0円',
        changeRate: 0,
        isPositive: true,
        unit: '円',
        type: 'averageSpend',
      },
    ];
  }

  const totalSales = safeRecords.reduce((sum, item) => sum + (item.sales || 0), 0);
  const totalTargetSales = safeRecords.reduce((sum, item) => sum + (item.targetSales || 0), 0);
  const totalCustomers = safeRecords.reduce((sum, item) => sum + (item.customers || 0), 0);
  const avgMonthlyCustomers = Math.round(totalCustomers / safeRecords.length);
  const overallAvgSpend = totalCustomers > 0 ? Math.round(totalSales / totalCustomers) : 0;
  const maxSpend = Math.max(...safeRecords.map((r) => r.averageSpend || 0));

  const targetAchievementRate =
    totalTargetSales > 0 ? ((totalSales / totalTargetSales) * 100).toFixed(1) : '0.0';

  const lastIndex = safeRecords.length - 1;
  const currentRecord = safeRecords[lastIndex];
  const prevRecord = lastIndex > 0 ? safeRecords[lastIndex - 1] : safeRecords[0];

  const salesChangeRate =
    prevRecord && prevRecord.sales > 0
      ? Number((((currentRecord.sales - prevRecord.sales) / prevRecord.sales) * 100).toFixed(1))
      : 0;

  const customersChangeRate =
    prevRecord && prevRecord.customers > 0
      ? Number((((currentRecord.customers - prevRecord.customers) / prevRecord.customers) * 100).toFixed(1))
      : 0;

  const spendChangeRate =
    prevRecord && prevRecord.averageSpend > 0
      ? Number((((currentRecord.averageSpend - prevRecord.averageSpend) / prevRecord.averageSpend) * 100).toFixed(1))
      : 0;

  return [
    {
      title: '売上高',
      value: formatNumber(totalSales),
      subValue: `目標達成率 ${targetAchievementRate}%`,
      changeRate: salesChangeRate,
      isPositive: salesChangeRate >= 0,
      unit: '円',
      type: 'sales',
    },
    {
      title: '客数',
      value: formatNumber(totalCustomers),
      subValue: `月平均 ${formatNumber(avgMonthlyCustomers)}人`,
      changeRate: customersChangeRate,
      isPositive: customersChangeRate >= 0,
      unit: '人',
      type: 'customers',
    },
    {
      title: '平均単価',
      value: formatNumber(overallAvgSpend),
      subValue: `最高単価 ${formatNumber(maxSpend)}円`,
      changeRate: spendChangeRate,
      isPositive: spendChangeRate >= 0,
      unit: '円',
      type: 'averageSpend',
    },
  ];
};

import { FC, useState, useMemo, ChangeEvent } from 'react';
import { FilterPeriod, MonthlyRecord } from './types';
import {
  monthlyRecords,
  filterRecordsByPeriod,
  calculateKpiSummary,
  formatCurrency,
  formatNumber,
} from './mockData';
import KpiCards from './components/KpiCards';
import ChartsView from './components/ChartsView';
import './index.css';

const App: FC = () => {
  const [period, setPeriod] = useState<FilterPeriod>('all');

  const safeRecords: MonthlyRecord[] = useMemo(() => {
    return Array.isArray(monthlyRecords) ? monthlyRecords : [];
  }, []);

  const filteredRecords = useMemo(() => {
    if (typeof filterRecordsByPeriod === 'function') {
      const records = filterRecordsByPeriod(safeRecords, period);
      return Array.isArray(records) ? records : [];
    }
    switch (period) {
      case 'first-half':
        return safeRecords.slice(0, 6);
      case 'second-half':
        return safeRecords.slice(6, 12);
      case 'all':
      default:
        return [...safeRecords];
    }
  }, [safeRecords, period]);

  const kpiData = useMemo(() => {
    if (typeof calculateKpiSummary === 'function') {
      const kpis = calculateKpiSummary(filteredRecords);
      return Array.isArray(kpis) ? kpis : [];
    }
    return [];
  }, [filteredRecords]);

  const handlePeriodChange = (e: ChangeEvent<HTMLSelectElement>) => {
    setPeriod(e.target.value as FilterPeriod);
  };

  return (
    <div className="dashboard-container">
      {/* ヘッダーエリア */}
      <header className="dashboard-header">
        <div className="header-title-group">
          <h1 className="dashboard-title">売上分析ダッシュボード</h1>
          <p className="dashboard-subtitle">
            月別売上高・来店客数・平均客単価の推移とKPIサマリー
          </p>
        </div>

        <div className="header-controls">
          <label htmlFor="period-select" style={{ fontSize: '0.875rem', color: '#475569', fontWeight: 500 }}>
            対象期間:
          </label>
          <select
            id="period-select"
            className="period-select"
            value={period}
            onChange={handlePeriodChange}
          >
            <option value="all">通年 (1月〜12月)</option>
            <option value="first-half">上半期 (1月〜6月)</option>
            <option value="second-half">下半期 (7月〜12月)</option>
          </select>
        </div>
      </header>

      {/* KPIサマリーカード */}
      <section aria-label="KPIサマリー">
        <KpiCards cards={kpiData} />
      </section>

      {/* グラフ分析エリア */}
      <section aria-label="グラフ推移">
        <ChartsView records={filteredRecords} />
      </section>

      {/* 月別データ詳細テーブル */}
      <section className="table-section" aria-label="月別実績データ一覧">
        <div>
          <h2 className="chart-title">月別実績明細</h2>
          <p className="chart-desc">各月の売上、目標対比達成率、来店客数および単価の詳細データ</p>
        </div>

        <div className="data-table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th className="th text-center">月度</th>
                <th className="th text-right">売上実績</th>
                <th className="th text-right">目標売上</th>
                <th className="th text-right">目標達成率</th>
                <th className="th text-right">来店客数</th>
                <th className="th text-right">平均客単価</th>
              </tr>
            </thead>
            <tbody>
              {filteredRecords.map((item) => {
                const achievementRate =
                  item.targetSales > 0
                    ? ((item.sales / item.targetSales) * 100).toFixed(1)
                    : '0.0';
                const isAchieved = item.sales >= item.targetSales;

                return (
                  <tr key={item.month}>
                    <td className="td text-center" style={{ fontWeight: 600 }}>
                      {item.month}
                    </td>
                    <td className="td text-right" style={{ fontWeight: 600 }}>
                      {formatCurrency(item.sales)}
                    </td>
                    <td className="td text-right" style={{ color: '#64748b' }}>
                      {formatCurrency(item.targetSales)}
                    </td>
                    <td
                      className="td text-right"
                      style={{
                        fontWeight: 600,
                        color: isAchieved ? '#059669' : '#dc2626',
                      }}
                    >
                      {achievementRate}%
                    </td>
                    <td className="td text-right">
                      {formatNumber(item.customers)} 人
                    </td>
                    <td className="td text-right">
                      {formatNumber(item.averageSpend)} 円
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
};

export default App;

export interface MonthlyRecord {
  month: string;
  sales: number;
  customers: number;
  averageSpend: number;
  targetSales: number;
}

export interface KpiCardData {
  title: string;
  value: string;
  subValue: string;
  changeRate: number;
  isPositive: boolean;
  unit: string;
  type: 'sales' | 'customers' | 'averageSpend';
}

export type FilterPeriod = 'all' | 'first-half' | 'second-half';

export type MetricType = 'sales' | 'customers' | 'averageSpend' | 'all';

