import { FC } from 'react';
import { JapaneseYen, Users, CreditCard, TrendingUp, TrendingDown } from 'lucide-react';
import { KpiCardData } from '../types';

interface KpiCardsProps {
  cards?: KpiCardData[];
}

const renderIcon = (type: KpiCardData['type']) => {
  switch (type) {
    case 'sales':
      return <JapaneseYen size={20} strokeWidth={2.2} />;
    case 'customers':
      return <Users size={20} strokeWidth={2.2} />;
    case 'averageSpend':
      return <CreditCard size={20} strokeWidth={2.2} />;
    default:
      return <JapaneseYen size={20} strokeWidth={2.2} />;
  }
};

const KpiCards: FC<KpiCardsProps> = ({ cards = [] }) => {
  return (
    <div className="kpi-grid">
      {cards.map((card, index) => {
        const badgeClass = card.isPositive ? 'kpi-badge kpi-badge-up' : 'kpi-badge kpi-badge-down';
        const formattedRate = `${card.isPositive ? '+' : ''}${card.changeRate}%`;

        return (
          <div key={`${card.type}-${index}`} className="kpi-card">
            <div className="kpi-header">
              <span className="kpi-title">{card.title}</span>
              <div className="kpi-icon-wrap">
                {renderIcon(card.type)}
              </div>
            </div>

            <div className="kpi-value-group">
              <span className="kpi-main-value">{card.value}</span>
              <span className="kpi-unit">{card.unit}</span>
            </div>

            <div className="kpi-footer">
              <span className={badgeClass}>
                {card.isPositive ? <TrendingUp size={14} /> : <TrendingDown size={14} />}
                前月比 {formattedRate}
              </span>
              <span className="kpi-subtext">{card.subValue}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default KpiCards;

import { FC, useState } from 'react';
import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { MonthlyRecord, MetricType } from '../types';

interface ChartsViewProps {
  records?: MonthlyRecord[];
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
  }>;
  label?: string;
}

const SalesTooltip: FC<CustomTooltipProps> = ({ active, payload, label }) => {
  if (active && payload && payload.length > 0) {
    return (
      <div className="custom-tooltip">
        <div className="tooltip-title">{label}の実績</div>
        {payload.map((entry, index) => (
          <div key={`tooltip-${index}`} className="tooltip-item">
            <span style={{ color: entry.color }}>{entry.name}:</span>
            <span style={{ fontWeight: 600 }}>{entry.value.toLocaleString()} 円</span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

const CustomerTooltip: FC<CustomTooltipProps> = ({ active, payload, label }) => {
  if (active && payload && payload.length > 0) {
    return (
      <div className="custom-tooltip">
        <div className="tooltip-title">{label}の実績</div>
        {payload.map((entry, index) => {
          const unit = entry.name.includes('客数') ? '人' : '円';
          return (
            <div key={`cust-tooltip-${index}`} className="tooltip-item">
              <span style={{ color: entry.color }}>{entry.name}:</span>
              <span style={{ fontWeight: 600 }}>
                {entry.value.toLocaleString()} {unit}
              </span>
            </div>
          );
        })}
      </div>
    );
  }
  return null;
};

const ChartsView: FC<ChartsViewProps> = ({ records = [] }) => {
  const [activeTab, setActiveTab] = useState<MetricType>('all');

  const formatSalesAxis = (val: number): string => {
    return `${Math.round(val / 10000)}万円`;
  };

  const formatCustomersAxis = (val: number): string => {
    return `${val.toLocaleString()}人`;
  };

  const formatSpendAxis = (val: number): string => {
    return `${val.toLocaleString()}円`;
  };

  const showSalesChart = activeTab === 'all' || activeTab === 'sales';
  const showCustomersChart = activeTab === 'all' || activeTab === 'customers' || activeTab === 'averageSpend';

  return (
    <div className="charts-section">
      <div className="chart-card">
        <div className="chart-header">
          <div>
            <h2 className="chart-title">業績推移分析</h2>
            <p className="chart-desc">月別の売上実績・目標および客数・単価の相関推移</p>
          </div>
          <div className="chart-tabs">
            <button
              type="button"
              className={activeTab === 'all' ? 'tab-btn tab-btn-active' : 'tab-btn'}
              onClick={() => setActiveTab('all')}
            >
              すべて表示
            </button>
            <button
              type="button"
              className={activeTab === 'sales' ? 'tab-btn tab-btn-active' : 'tab-btn'}
              onClick={() => setActiveTab('sales')}
            >
              売上・目標
            </button>
            <button
              type="button"
              className={activeTab === 'customers' ? 'tab-btn tab-btn-active' : 'tab-btn'}
              onClick={() => setActiveTab('customers')}
            >
              客数・平均単価
            </button>
          </div>
        </div>

        {showSalesChart && (
          <div>
            <div style={{ marginBottom: 12 }}>
              <h3 style={{ fontSize: '0.9375rem', fontWeight: 600, color: '#334155' }}>
                売上高 vs 目標売上推移
              </h3>
            </div>
            <div className="chart-body">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={records} margin={{ top: 10, right: 20, left: 20, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                  <XAxis dataKey="month" stroke="#64748b" tick={{ fontSize: 12 }} />
                  <YAxis
                    stroke="#64748b"
                    tick={{ fontSize: 12 }}
                    tickFormatter={formatSalesAxis}
                    width={70}
                  />
                  <Tooltip content={<SalesTooltip />} />
                  <Legend
                    verticalAlign="top"
                    align="right"
                    wrapperStyle={{ paddingBottom: '10px', fontSize: '12px' }}
                  />
                  <Bar
                    dataKey="sales"
                    name="売上実績"
                    fill="#3b82f6"
                    radius={[4, 4, 0, 0]}
                    maxBarSize={40}
                  />
                  <Line
                    type="monotone"
                    dataKey="targetSales"
                    name="売上目標"
                    stroke="#ef4444"
                    strokeWidth={2.5}
                    strokeDasharray="4 4"
                    dot={{ r: 3, fill: '#ef4444' }}
                    activeDot={{ r: 6 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {showCustomersChart && (
          <div style={{ marginTop: showSalesChart ? 32 : 0 }}>
            <div style={{ marginBottom: 12 }}>
              <h3 style={{ fontSize: '0.9375rem', fontWeight: 600, color: '#334155' }}>
                来客数 & 客単価（二軸推移）
              </h3>
            </div>
            <div className="chart-body">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={records} margin={{ top: 10, right: 20, left: 20, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                  <XAxis dataKey="month" stroke="#64748b" tick={{ fontSize: 12 }} />
                  <YAxis
                    yAxisId="left"
                    stroke="#8b5cf6"
                    tick={{ fontSize: 12 }}
                    tickFormatter={formatCustomersAxis}
                    width={65}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    stroke="#10b981"
                    tick={{ fontSize: 12 }}
                    tickFormatter={formatSpendAxis}
                    domain={['dataMin - 200', 'dataMax + 200']}
                    width={65}
                  />
                  <Tooltip content={<CustomerTooltip />} />
                  <Legend
                    verticalAlign="top"
                    align="right"
                    wrapperStyle={{ paddingBottom: '10px', fontSize: '12px' }}
                  />
                  <Bar
                    yAxisId="left"
                    dataKey="customers"
                    name="来客数"
                    fill="#a78bfa"
                    radius={[4, 4, 0, 0]}
                    maxBarSize={40}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="averageSpend"
                    name="平均単価"
                    stroke="#10b981"
                    strokeWidth={2.5}
                    dot={{ r: 3, fill: '#10b981' }}
                    activeDot={{ r: 6 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChartsView;
